+  expiresIn?: string;
+  issuer?: string;
+  audience?: string;
+}
+
+// Blacklist for revoked tokens (use Redis in production)
+const tokenBlacklist = new Set<string>();
+
+/**
+ * Generate JWT token
+ */
+export async function generateToken(
+  payload: JWTPayload,
+  secret: string,
+  options: TokenOptions = {}
+): Promise<string> {
+  const {
+    expiresIn = '24h',
+    issuer = 'binG',
+    audience = 'binG-users',
+  } = options;
+
+  const jti = crypto.randomUUID();
+  const now = Math.floor(Date.now() / 1000);
+  
+  const token = await new SignJWT({ ...payload, jti })
+    .setProtectedHeader({ alg: 'HS256' })
+    .setIssuedAt(now)
+    .setExpirationTime(expiresIn)
+    .setIssuer(issuer)
+    .setAudience(audience)
+    .sign(new TextEncoder().encode(secret));
+
+  logger.debug('Token generated', { 
+    userId: payload.userId, 
+    jti,
+    expiresIn 
+  });
+
+  return token;
+}
+
+/**
+ * Verify JWT token
+ */
+export async function verifyToken(
+  token: string,
+  secret: string
+): Promise<JWTPayload> {
+  try {
+    // Check blacklist
+    const decoded = JSON.parse(
+      Buffer.from(token.split('.')[1], 'base64').toString()
+    );
+    
+    if (tokenBlacklist.has(decoded.jti)) {
+      throw new Error('Token has been revoked');
+    }
+
+    const { payload } = await jwtVerify(
+      token,
+      new TextEncoder().encode(secret),
+      {
+        issuer: 'binG',
+        audience: 'binG-users',
+      }
+    );
+
+    return payload as JWTPayload;
+  } catch (error: any) {
+    logger.error('Token verification failed', { 
+      error: error.message,
+      tokenPrefix: token.slice(0, 10) 
+    });
+    throw new Error(`Invalid token: ${error.message}`);
+  }
+}
+
+/**
+ * Revoke token (add to blacklist)
+ */
+export function revokeToken(token: string): void {
+  try {
+    const decoded = JSON.parse(
+      Buffer.from(token.split('.')[1], 'base64').toString()
+    );
+    tokenBlacklist.add(decoded.jti);
+    logger.debug('Token revoked', { jti: decoded.jti });
+  } catch (error: any) {
+    logger.warn('Failed to revoke token', error);
+  }
+}
+
+/**
+ * Extract token from Authorization header
+ */
+export function extractTokenFromHeader(authHeader: string | null): string | null {
+  if (!authHeader || !authHeader.startsWith('Bearer ')) {
+    return null;
+  }
+  return authHeader.slice(7);
+}
+
+/**
+ * Middleware for Next.js API routes
+ */
+export async function authMiddleware(
+  request: Request,
+  options: { 
+    allowAnonymous?: boolean;
+    requiredRole?: 'user' | 'admin';
+  } = {}
+): Promise<{ 
+  authenticated: boolean;
+  userId?: string;
+  payload?: JWTPayload;
+  error?: string;
+}> {
+  const authHeader = request.headers.get('authorization');
+  const token = extractTokenFromHeader(authHeader);
+
+  if (!token) {
+    if (options.allowAnonymous) {
+      return { authenticated: false };
+    }
+    return { 
+      authenticated: false, 
+      error: 'Authorization header required' 
+    };
+  }
+
+  try {
+    const secret = process.env.JWT_SECRET || 'fallback-secret-change-in-production';
+    const payload = await verifyToken(token, secret);
+
+    if (options.requiredRole && payload.role !== options.requiredRole) {
+      return {
+        authenticated: false,
+        error: `Required role: ${options.requiredRole}`,
+      };
+    }
+
+    return {
+      authenticated: true,
+      userId: payload.userId,
+      payload,
+    };
+  } catch (error: any) {
+    return {
+      authenticated: false,
+      error: error.message,
+    };
+  }
+}
+
+/**
+ * Refresh token rotation
+ */
+export async function refreshToken(
+  oldToken: string,
+  secret: string
+): Promise<string> {
+  const payload = await verifyToken(oldToken, secret);
+  
+  // Revoke old token
+  revokeToken(oldToken);
+  
+  // Generate new token with same payload
+  return generateToken(payload, secret);
+}
