+        } catch (error: any) {
+          return {
+            content: [{ type: 'text', text: `List error: ${error.message}` }],
+            isError: true,
+          }
+        }
+      }
+    )
+
+    // Tool: Get Sandbox Info
+    this.server.tool(
+      'get_sandbox_info',
+      'Get information about the sandbox including status, URL, region, and resource usage.',
+      {
+        type: 'object',
