+                  data: { type: 'object', description: 'Task data' },
+                },
+              },
+            },
+            maxConcurrentTasks: {
+              type: 'number',
+              description: 'Maximum number of concurrent tasks (default: 10)',
+            },
+            timeout: {
+              type: 'number',
